events.command:
/usr/bin/bash -lc 'set -e
forward=/workspace/final_answer/trimmed_forward.fastqsanger.gz
reverse=/workspace/final_answer/trimmed_reverse.fastqsanger.gz
gzip -t "$forward"
gzip -t "$reverse"
perl -e '"'
use strict; use warnings;
sub next_record {
    my ("'$fh, $label) = @_;
    my $h = <$fh>;
    return undef unless defined $h;
    my $s = <$fh>; my $p = <$fh>; my $q = <$fh>;
    die "$label: truncated FASTQ record'"\\n\" unless defined "'$s && defined $p && defined $q;
    chomp($h, $s, $p, $q);
    die "$label: malformed record'"\\n\" unless "'$h =~ /''^@/ && $p =~ /''^'"\\+/;
    die \""'$label: sequence/quality length mismatch'"\\n\" unless length("'$s) == length($q);
    my $key = $h; $key =~ s/''^@//; $key =~ s/'"\\s.*"'$//; $key =~ s{/[12]$}{};
    my $n = () = $s =~ /[Nn]/g;
    my $low = 0;
    for (my $i=0; $i<length($q); $i++) { $low++ if ord(substr($q,$i,1)) < 53; }
    return {key=>$key, len=>length($s), n=>$n, low=>$low, h=>$h};
}
open(my $f, "-|", "gzip", "-cd", "/workspace/final_answer/trimmed_forward.fastqsanger.gz") or die "open forward: $!";
open(my $r, "-|", "gzip", "-cd", "/workspace/final_answer/trimmed_reverse.fastqsanger.gz") or die "open reverse: $!";
my ($pairs, $f_bad, $r_bad) = (0,0,0);
while (1) {
    my $a = next_record($f, "forward");
    my $b = next_record($r, "reverse");
    last if !defined($a) && !defined($b);
    die "mate count mismatch at pair $pairs'"\\n\" if "'!defined($a) || !defined($b);
    $pairs++;
    die "mate ID mismatch at pair $pairs: $a->{h} vs $b->{h}'"\\n\" if "'$a->{key} ne $b->{key};
    $f_bad++ if $a->{len} < 15 || $a->{n} > 5 || ($a->{len} && $a->{low}/$a->{len} > 0.40);
    $r_bad++ if $b->{len} < 15 || $b->{n} > 5 || ($b->{len} && $b->{low}/$b->{len} > 0.40);
}
close($f); close($r);
die "validation failed: forward violations=$f_bad reverse violations=$r_bad'"\\n\" if "'$f_bad || $r_bad;
print "pairs=$pairs forward_violations=$f_bad reverse_violations=$r_bad'"\\n\";
' 
md5sum \""'$forward" "$reverse"
file "$forward" "$reverse"'
